"""Lazy, composable iteration specifications.

Iter pipelines do not consume their input until the result is iterated. Use
``.all()`` to collect a list, or ``.first()`` to select a matching element.
"""
import itertools

from boltons.iterutils import chunked_iter, unique_iter, windowed_iter
from .core import (T, SKIP, STOP, Path, TargetRegistry, GlomError, glom,
                   _MISSING)


def _iterate(target, scope):
    handler = scope[TargetRegistry].get_handler('iterate', target,
                                                path=scope[Path])
    return iter(handler(target))


def _matches(value, spec, scope):
    try:
        result = scope[glom](value, spec, scope)
    except GlomError:
        return False
    return result is not SKIP and result is not STOP and bool(result)


class First(object):
    """Return the first input element matching *key*, or *default*.

    The key is a glom spec (T by default, selecting the first truthy item).
    Like Python's filter, selection returns the original input element.
    """
    def __init__(self, key=T, default=None):
        self.key = key
        self.default = default

    def glomit(self, target, scope):
        for value in _iterate(target, scope):
            if _matches(value, self.key, scope):
                return value
        return self.default

    def __repr__(self):
        return 'First(%r, default=%r)' % (self.key, self.default)


class Iter(object):
    """Lazily apply *subspec* to each element of an iterable target.

    Chained transformations return new Iter specs, leaving the original
    reusable. SKIP results are omitted and STOP terminates iteration.
    """
    def __init__(self, subspec=T, sentinel=STOP):
        self.subspec = subspec
        self.sentinel = sentinel
        self._operations = ()

    def _chain(self, name, *args, **kwargs):
        new = type(self)(self.subspec, sentinel=self.sentinel)
        new._operations = self._operations + ((name, args, kwargs),)
        return new

    def map(self, subspec):
        """Apply a glom spec to each element."""
        return self._chain('map', subspec)

    def filter(self, key=T):
        """Keep elements for which *key* evaluates to a truthy value."""
        return self._chain('filter', key)

    def chunked(self, size, **kwargs):
        """Group elements into lists, with a possibly shorter final chunk."""
        return self._chain('chunked', size, **kwargs)

    def windowed(self, size):
        """Yield overlapping windows of *size* elements."""
        return self._chain('windowed', size)

    def flatten(self):
        """Flatten one level of iterables."""
        return self._chain('flatten')

    def unique(self, key=T):
        """Keep the first element for each distinct key, in input order."""
        return self._chain('unique', key)

    def slice(self, *args):
        """Lazily slice the stream, as with itertools.islice."""
        return self._chain('slice', *args)

    def limit(self, count):
        return self.slice(count)

    def takewhile(self, key=T):
        """Yield elements until *key* first becomes false."""
        return self._chain('takewhile', key)

    def dropwhile(self, key=T):
        """Discard the leading elements for which *key* is true."""
        return self._chain('dropwhile', key)

    def enumerate(self, start=0):
        return self._chain('enumerate', start)

    def all(self):
        """Collect this pipeline into a list."""
        return (self, list)

    def first(self, key=T, default=None):
        """Select the first matching element from this pipeline."""
        return (self, First(key=key, default=default))

    def _map(self, iterator, spec, scope):
        for index, value in enumerate(iterator):
            child = scope.new_child({Path: scope[Path] + [index]})
            result = scope[glom](value, spec, child)
            if result is self.sentinel:
                break
            if result is not SKIP:
                yield result

    def _apply(self, iterator, name, args, kwargs, scope):
        if name == 'map':
            return self._map(iterator, args[0], scope)
        if name == 'filter':
            return (value for value in iterator
                    if _matches(value, args[0], scope))
        if name == 'chunked':
            return chunked_iter(iterator, *args, **kwargs)
        if name == 'windowed':
            return windowed_iter(iterator, *args)
        if name == 'flatten':
            return itertools.chain.from_iterable(iterator)
        if name == 'unique':
            return unique_iter(iterator,
                               key=lambda value: scope[glom](value, args[0], scope))
        if name == 'slice':
            return itertools.islice(iterator, *args)
        if name == 'enumerate':
            return enumerate(iterator, *args)
        predicate = lambda value: _matches(value, args[0], scope)
        if name == 'takewhile':
            return itertools.takewhile(predicate, iterator)
        if name == 'dropwhile':
            return itertools.dropwhile(predicate, iterator)
        raise ValueError('unknown iteration operation: %r' % name)

    def glomit(self, target, scope):
        iterator = self._map(_iterate(target, scope), self.subspec, scope)
        for name, args, kwargs in self._operations:
            iterator = self._apply(iterator, name, args, kwargs, scope)
        return iterator

    def __repr__(self):
        result = 'Iter(%r)' % (self.subspec,)
        for name, args, kwargs in self._operations:
            params = [repr(arg) for arg in args]
            params.extend('%s=%r' % item for item in kwargs.items())
            result += '.%s(%s)' % (name, ', '.join(params))
        return result
